const catalogue = $('Service catalogue').all();
const checks = items.map((item, index) => {
  const target = catalogue[index]?.json ?? {};
  const statusCode = Number(item.json.statusCode ?? 0);
  const rawError = item.json.error?.message ?? item.json.error ?? item.json.message ?? '';
  return {
    service: target.service ?? `service-${index + 1}`,
    url: target.url ?? '',
    statusCode,
    healthy: (statusCode >= 200 && statusCode < 400) || statusCode === 401 || statusCode === 403,
    error: typeof rawError === 'string' ? rawError : JSON.stringify(rawError),
  };
});

const failures = checks.filter((check) => !check.healthy);
const fingerprint = failures
  .map((check) => `${check.service}:${check.statusCode}:${check.error}`)
  .sort()
  .join('|');
const state = $getWorkflowStaticData('global');

if (fingerprint) {
  if (state.candidateFingerprint === fingerprint) {
    state.candidateCount = Number(state.candidateCount ?? 0) + 1;
  } else {
    state.candidateFingerprint = fingerprint;
    state.candidateCount = 1;
  }
  if (state.candidateCount < 2 || state.notifiedFingerprint === fingerprint) {
    return [];
  }
} else {
  state.candidateFingerprint = '';
  state.candidateCount = 0;
  if (!state.notifiedFingerprint) {
    state.notifiedFingerprint = '';
    return [];
  }
}

const recovered = failures.length === 0;
state.notifiedFingerprint = fingerprint;
const message = recovered
  ? `All ${checks.length} monitored ThornixOS services are healthy again.`
  : failures.map((check) => {
      const detail = check.statusCode ? `HTTP ${check.statusCode}` : (check.error || 'connection failed');
      return `${check.service}: ${detail}`;
    }).join('\n');

return [{ json: {
  topic: 'thornixos-ops',
  title: recovered ? 'ThornixOS fleet recovered' : `${failures.length} ThornixOS service${failures.length === 1 ? '' : 's'} unhealthy`,
  message,
  priority: recovered ? 3 : 5,
  tags: recovered ? ['heavy_check_mark', 'thornixos'] : ['rotating_light', 'thornixos'],
  click: 'https://soc.guildedthorn.arpa:3000/',
} }];
